import sys

def solve():
    # Read input
    try:
        line = sys.stdin.read().split()
        if not line:
            return
        A = [int(x) for x in line]
    except ValueError:
        return

    target = [1, 2, 3, 4, 5]

    # Try swapping every adjacent pair
    possible = False
    for i in range(len(A) - 1):
        # Create a copy to simulate swap
        temp = A[:]
        temp[i], temp[i+1] = temp[i+1], temp[i]

        if temp == target:
            possible = True
            break

    if possible:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()
